<script setup>
import { money, safeError } from './settlementFinance.js';
import { partyKinds } from './settlementManagement.js';
import SettlementEconomicSegments from './SettlementEconomicSegments.vue';
defineProps({ row: { type: Object, required: true } });
const fields = { buyer_name: '买方', seller_name: '卖方', product_version_name: '产品版本', source_order_no: '原订单', batch_no: '批次', reference_batch_no: '原批次', reference_settlement_no: '原清算单', reference_settlement_id: '原清算关联', reference_baseline_hash: '原最终基线校验值', baseline_hash: '最终基线校验值', baseline_version: '最终确认版本', baseline_created_at: '最终确认时间', segment_id: '经济段', segment_start: '经济段起点', segment_end: '经济段终点', segment_side: '经济段方向', rule_version: '冻结规则版本' };
const shareKeys = { platform: 'platform_fee', provider: 'provider_share', service: 'service_share', expert: 'expert_fee', channel: 'channel_fee' };
const fundLabels = { payable_amount: '应付金额', paid_amount: '已付款', payable_offset_amount: '应付已抵扣', unpaid_amount: '未付余额', receivable_amount: '应追回', recovered_amount: '已追回', receivable_offset_amount: '应收已抵扣', unrecovered_amount: '未追回余额' };
const direction = { payable: '应付', receivable: '应追回', internal: '内部收益' };
const positionKinds = { cost: '成本', profit: '利润 / 损失', loss: '独立损失', funding_return: '原补差付款方返还应付', funding_absorption_return: '平台内部吸收恢复' };
const versionFields = { recorded_at: '投影记录时间', projection_hash: '投影校验值', source_settlement_id: '原清算关联', source_hash: '原最终基线校验值', change_id: '版本变更关联', window_hash: '经济窗口校验值', receipt_hash: '生效回执校验值' };
const fundingProofFields = { source: '补款来源', request_id: '原补款申请', proof_hash: '原补款凭据校验值', manual_evidence_id: '人工付款凭据关联', manual_evidence_hash: '人工付款凭据校验值' };
const cashFields = { buyer_cash_refund: '买方实际现金退款', buyer_cash_amount: '买方实际现金退款', gross_amount: '财务收入冲回（含补差对应部分）', external_funding_return: '原补差付款方返还权益', absorption_reversal: '平台吸收冲回（非买方现金）' };
function returnState(row) {
  const decimal = value => typeof value === 'string' && /^\d+(?:\.\d+)?$/.test(value);
  if (![row.amount, row.paid_amount, row.offset_amount, row.remaining_amount].every(decimal)) return '返还权益，结算证据未提供';
  const positive = value => /[1-9]/.test(value);
  if (positive(row.remaining_amount)) return positive(row.paid_amount) || positive(row.offset_amount) ? '部分处理，仍有待付' : '待付款 / 抵销';
  if (positive(row.paid_amount) && positive(row.offset_amount)) return '已登记付款及抵销';
  if (positive(row.paid_amount)) return '已登记付款';
  if (positive(row.offset_amount)) return '已抵销';
  return positive(row.amount) ? '返还权益，结算证据未闭合' : '无待付金额';
}
</script>
<template><section class="report-evidence" aria-label="清算明细证据"><dl><template v-for="(label, key) in fields" :key="key"><template v-if="row[key] != null && row[key] !== ''"><dt>{{ label }}</dt><dd>{{ row[key] }}</dd></template></template></dl>
  <div v-if="row.share_rates || row.platform_fee != null" class="table-scroll"><table><thead><tr><th>收益类别</th><th>最终基线比例</th><th>规则比例</th><th>金额</th></tr></thead><tbody><tr v-for="(label, kind) in partyKinds" :key="kind"><td>{{ label }}</td><td>{{ row.share_rates?.[kind] == null ? '未知' : row.share_rates[kind] + '%' }}</td><td>{{ row.configured_share_rates?.[kind] == null ? '未知' : row.configured_share_rates[kind] + '%' }}</td><td>{{ money(row[shareKeys[kind]]) }}</td></tr></tbody></table></div>
  <div v-if="row.participants?.length" class="table-scroll"><table><thead><tr><th>实际收益主体</th><th>类别</th><th>成本</th><th>利润</th><th>承担损失</th><th>净应收</th><th>平台补差吸收损失</th><th>基线应收合计</th><th>补差后净应收</th></tr></thead><tbody><tr v-for="(p, i) in row.participants" :key="p.participant_id || i"><td>{{ p.participant_name || '未分配' }}</td><td>{{ partyKinds[p.participant_type] || p.participant_type }}</td><td>{{ money(p.cost_amount) }}</td><td>{{ money(p.profit_share) }}</td><td>{{ money(p.loss_amount) }}</td><td>{{ money(p.total_receivable) }}</td><td>{{ money(p.funding_absorption_loss) }}</td><td>{{ money(p.baseline_total_receivable) }}</td><td>{{ money(p.net_total_receivable) }}</td></tr></tbody></table></div>
  <section v-if="row.supplementary_funding && row.supplementary_funding.status !== 'not_required'" aria-label="独立补差来源与承担证据"><h4>独立补差来源与承担证据</h4><dl><dt>状态</dt><dd>{{ ({ covered: '已核验覆盖', uncovered: '未覆盖', unproven: '证据未通过核验' })[row.supplementary_funding.status] || row.supplementary_funding.status || '未知' }}</dd><dt>来源</dt><dd>{{ ({ platform_absorption: '平台吸收', external_receipt: '外部补差入账' })[row.supplementary_funding.kind] || '未提供' }}</dd><dt>补差金额</dt><dd>{{ money(row.supplementary_funding.amount) }} {{ row.supplementary_funding.currency || '' }}</dd><dt>承担主体</dt><dd>{{ row.supplementary_funding.bearer?.participant_name || '未提供' }}</dd><template v-for="[key, label] in [['request_id','补差申请关联'],['source_key','补差来源关联'],['transaction_id','吸收凭证关联'],['evidence_hash','核验校验值'],['effective_at','核验生效时间']]" :key="key"><template v-if="row.supplementary_funding[key]"><dt>{{ label }}</dt><dd>{{ row.supplementary_funding[key] }}</dd></template></template><template v-for="[key, label] in [['request_hash','申请证据校验值'],['proof_hash','补差凭据校验值'],['baseline_hash','关联基线校验值']]" :key="key"><template v-if="row.supplementary_funding.evidence?.[key]"><dt>{{ label }}</dt><dd>{{ row.supplementary_funding.evidence[key] }}</dd></template></template></dl><p v-if="row.supplementary_funding.reason">{{ safeError({ response: { data: { detail: row.supplementary_funding.reason } } }) }}</p></section>
  <template v-if="row.funds"><h4>资金与回收证据</h4><p>{{ row.funds.known ? '资金证据已核实' : '资金证据未完整核实，不推断为已结清' }}</p><dl><template v-for="(label, key) in fundLabels" :key="key"><dt>{{ label }}</dt><dd>{{ money(row.funds[key]) }}</dd></template></dl><p v-for="issue in row.funds.issues || []" :key="issue">{{ safeError({ response: { data: { detail: issue } } }) }}</p><div v-if="row.funds.positions?.length" class="table-scroll"><table><thead><tr><th>资金行关联</th><th>款项</th><th>方向</th><th>金额</th><th>未结</th><th>币种</th></tr></thead><tbody><tr v-for="p in row.funds.positions" :key="p.id"><td>{{ p.id }}</td><td>{{ positionKinds[p.kind] || p.kind }}</td><td>{{ direction[p.direction] || p.direction }}</td><td>{{ money(p.amount) }}</td><td>{{ money(p.remaining_amount) }}</td><td>{{ p.currency }}</td></tr></tbody></table></div><div v-if="row.funds.evidence?.length" class="table-scroll"><table><thead><tr><th>凭证关联</th><th>凭据</th><th>类型</th><th>金额</th><th>复核人</th><th>确认时间</th></tr></thead><tbody><tr v-for="(e, i) in row.funds.evidence" :key="e.allocation_id || i"><td>{{ e.transaction_id }}</td><td>{{ e.reference }}</td><td>{{ ({ payout: '付款', recovery: '回款', offset: '抵扣' })[e.kind] }} · {{ e.mode === 'simulated' ? '模拟' : '人工登记' }}</td><td>{{ money(e.amount) }}</td><td>{{ e.reviewer_id }}</td><td>{{ e.confirmed_at }}</td></tr></tbody></table></div></template>
  <section v-if="row.buyer_cash_refund != null || row.buyer_cash_amount != null || row.funded_refund?.buyer_cash_amount != null" aria-label="现金退款与补差返还区分"><h4>现金退款与财务冲回</h4><dl><template v-for="(label, key) in cashFields" :key="key"><template v-if="(row[key] ?? row.funded_refund?.[key]) != null && !(key === 'buyer_cash_amount' && row.buyer_cash_refund != null)"><dt>{{ label }}</dt><dd>{{ money(row[key] ?? row.funded_refund?.[key]) }}</dd></template></template></dl><p>补差返还不增加买方现金退款；人工付款登记或抵销不代表银行自动到账验证。</p></section>
  <section v-if="row.funding_returns?.length" aria-label="原补差付款方返还权益"><h4>原补差付款方返还权益（独立应付）</h4><section v-for="(r, i) in row.funding_returns" :key="r.position_id || i"><h4>{{ r.participant_name || r.bearer?.participant_name || '原补差付款方' }}</h4><dl><dt>处理状态</dt><dd>{{ returnState(r) }}</dd><dt>返还权益</dt><dd>{{ money(r.amount) }} {{ r.currency }}</dd><template v-for="[key, label] in [['paid_amount','已登记付款'],['offset_amount','已抵销'],['remaining_amount','待付余额']]" :key="key"><template v-if="r[key] != null"><dt>{{ label }}</dt><dd>{{ money(r[key]) }}</dd></template></template><template v-for="[key, label] in [['source_order_no','原订单'],['reference_settlement_no','原清算单'],['reference_settlement_id','原清算关联'],['source_settlement_id','原清算关联'],['position_id','独立返还资金行'],['funding_request_id','原补差申请'],['funding_proof_hash','原补差凭据校验值'],['manual_evidence_id','人工付款凭据关联'],['manual_evidence_hash','人工付款凭据校验值']]" :key="key"><template v-if="r[key]"><dt>{{ label }}</dt><dd>{{ r[key] }}</dd></template></template><template v-if="r.reference_batch_nos?.length"><dt>原批次</dt><dd>{{ r.reference_batch_nos.join('、') }}</dd></template><dt>银行到账验证</dt><dd>{{ r.bank_receipt_verified === false ? '否' : '未提供，不推断到账' }}</dd></dl></section></section>
  <section v-if="row.funded_refund?.funding_returns?.length" aria-label="冻结补差返还来源凭据"><h4>冻结补差返还来源凭据（不代表已支付）</h4><dl v-for="(r, i) in row.funded_refund.funding_returns" :key="i"><dt>原补差付款方</dt><dd>{{ r.bearer?.participant_name || '未提供' }}</dd><template v-for="[key, label] in [['source_settlement_id','原清算关联'],['funding_request_id','原补差申请'],['funding_proof_hash','原补差凭据校验值'],['manual_evidence_id','人工付款凭据关联'],['manual_evidence_hash','人工付款凭据校验值']]" :key="key"><template v-if="r[key]"><dt>{{ label }}</dt><dd>{{ r[key] }}</dd></template></template></dl></section>
  <section v-if="row.version_funding" aria-label="版本变更原补款投影证据"><h4>版本变更原补款投影证据</h4><dl><dt>权益类别</dt><dd>{{ ({ external_payer_return: '原外部补款付款方返还权益', internal_absorption_restoration: '平台内部吸收恢复' })[row.version_funding.credit_kind] || '类别未提供，不推断付款' }}</dd><template v-if="row.version_funding.credit_kind === 'external_payer_return'"><dt>外部付款方返还权益</dt><dd>{{ money(row.version_funding.external_return_amount) }} {{ row.version_funding.currency }}</dd></template><template v-if="row.version_funding.credit_kind === 'internal_absorption_restoration'"><dt>平台内部吸收恢复金额</dt><dd>{{ money(row.version_funding.internal_absorption_return) }} {{ row.version_funding.currency }}</dd></template><dt>处理策略</dt><dd>{{ ({ return_unused_to_original_payer_not_target: '未使用补款返还原付款方，不转给目标版本', restore_unused_platform_absorption_not_target: '未使用平台吸收恢复内部权益，不转给目标版本' })[row.version_funding.policy] || row.version_funding.policy || '未提供' }}</dd><template v-for="(label, key) in versionFields" :key="key"><template v-if="row.version_funding[key]"><dt>{{ label }}</dt><dd>{{ row.version_funding[key] }}</dd></template></template><template v-for="(label, key) in fundingProofFields" :key="key"><template v-if="row.version_funding.funding?.[key]"><dt>{{ label }}</dt><dd>{{ key === 'source' ? ({ external_receipt: '外部人工补款', platform_absorption: '平台内部吸收' })[row.version_funding.funding[key]] || row.version_funding.funding[key] : row.version_funding.funding[key] }}</dd></template></template><template v-if="row.version_funding.funding?.bearer?.participant_name"><dt>原补款承担主体</dt><dd>{{ row.version_funding.funding.bearer.participant_name }}</dd></template></dl><p>{{ row.version_funding.credit_kind === 'internal_absorption_restoration' ? '内部权益恢复，不是外部应付款、已付款或买方现金退款。' : '投影为返还权益，不代表已经付款；实际处理以资金凭证及余额为准。' }} 不代表银行到账验证。</p><div v-if="row.version_funding.credits?.length" class="table-scroll"><table><thead><tr><th>投影资金行</th><th>权益类别</th><th>方向</th><th>金额</th><th>币种</th></tr></thead><tbody><tr v-for="p in row.version_funding.credits" :key="p.id"><td>{{ p.id }}</td><td>{{ positionKinds[p.kind] || p.kind }}</td><td>{{ direction[p.direction] || p.direction }}</td><td>{{ money(p.amount) }}</td><td>{{ p.currency }}</td></tr></tbody></table></div></section>
  <SettlementEconomicSegments :segments="row.economic_segments" />
</section></template>
<style scoped>.report-evidence{min-width:0;font-size:12px}.report-evidence dl{display:grid;grid-template-columns:160px minmax(0,1fr);gap:10px}.report-evidence dd{margin:0;overflow-wrap:anywhere}.report-evidence dt{color:#697586}.table-scroll{max-width:100%;overflow:auto;margin:12px 0}table{border-collapse:collapse;width:100%;font-size:12px}th,td{padding:10px;border-bottom:1px solid #e5e6eb;white-space:nowrap;text-align:left}th{background:#f7f8fa;font-weight:500}@media(max-width:600px){.report-evidence dl{grid-template-columns:1fr;gap:6px}}</style>
